<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\WhatsAppSupportService;

if(!Auth::can('support.manage')&&!Auth::can('settings.manage')){http_response_code(403);exit('Acesso negado.');}
$tenantId=(int)(Auth::tenantId()??0);if($tenantId<1){http_response_code(403);exit('Selecione uma empresa para abrir a Central de Atendimento.');}
$service=new WhatsAppSupportService();

$filter=strtolower(trim((string)($_GET['filter']??'all')));$search=mb_substr(trim((string)($_GET['q']??'')),0,100);$selectedId=(int)($_GET['id']??0);
$backUrl=static function(array $extra=[])use($filter,$search):string{$params=[];if($filter!=='all')$params['filter']=$filter;if($search!=='')$params['q']=$search;$params=array_merge($params,$extra);return app_url('support.php'.($params?'?'.http_build_query($params):''));};

if(($_GET['ajax']??'')==='peek'){
    header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, private, max-age=0');
    try{
        $id=(int)($_GET['id']??0);$counters=$service->counters($pdo,$tenantId);$payload=['ok'=>true,'counters'=>$counters,'latest_message_id'=>0,'mode'=>null,'last_activity_at'=>null];
        if($id>0){$q=$pdo->prepare('SELECT mode,last_activity_at,(SELECT MAX(m.id) FROM whatsapp_messages m WHERE m.tenant_id=c.tenant_id AND m.conversation_id=c.id) latest_message_id FROM whatsapp_conversations c WHERE c.id=? AND c.tenant_id=? LIMIT 1');$q->execute([$id,$tenantId]);if($row=$q->fetch(PDO::FETCH_ASSOC)){$payload['latest_message_id']=(int)($row['latest_message_id']??0);$payload['mode']=(string)$row['mode'];$payload['last_activity_at']=$row['last_activity_at'];}}
        echo json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    }catch(Throwable){http_response_code(503);echo json_encode(['ok'=>false,'error'=>'Não foi possível atualizar a Central agora.'],JSON_UNESCAPED_UNICODE);}
    exit;
}

if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');$conversationId=(int)($_POST['conversation_id']??0);
    try{
        if($action==='start'){
            $started=$service->startConversation($pdo,$tenantId,(int)(Auth::id()??0),(string)($_POST['phone']??''),(string)($_POST['message']??''));
            $conversationId=(int)$started['id'];em_flash('ok','Conversa aberta. A primeira mensagem, quando informada, foi colocada na fila do EventMenu Connect.');
        }
        elseif($action==='assume'){$service->assume($pdo,$tenantId,$conversationId,(int)(Auth::id()??0));em_flash('ok','Atendimento assumido. O automático ficou pausado para esta conversa.');}
        elseif($action==='resume'){$service->resumeAutomatic($pdo,$tenantId,$conversationId,(int)(Auth::id()??0));em_flash('ok','Conversa devolvida ao atendimento automático no ponto em que estava.');}
        elseif($action==='send'){$service->sendManual($pdo,$tenantId,$conversationId,(int)(Auth::id()??0),(string)($_POST['message']??''));em_flash('ok','Mensagem colocada na fila do EventMenu Connect.');}
        else throw new RuntimeException('Ação de atendimento inválida.');
    }catch(Throwable $e){em_flash('error',$e->getMessage());}
    header('Location: '.$backUrl($conversationId>0?['id'=>$conversationId]:[]));exit;
}

$counters=$service->counters($pdo,$tenantId);$inbox=$service->inbox($pdo,$tenantId,$filter,$search,120);if($selectedId<1&&$inbox)$selectedId=(int)$inbox[0]['id'];
$detail=null;if($selectedId>0){try{$service->markRead($pdo,$tenantId,$selectedId);$detail=$service->conversation($pdo,$tenantId,$selectedId,300);$counters=$service->counters($pdo,$tenantId);}catch(Throwable$e){em_flash('error',$e->getMessage());$selectedId=0;}}
$selected=$detail['conversation']??null;$messages=$detail['messages']??[];$activeOrder=$detail['active_order']??null;$activeItems=$detail['active_order_items']??[];$recentOrders=$detail['recent_orders']??[];$addresses=$detail['addresses']??[];
$statusLabel=static fn(string$s):string=>match($s){'queued'=>'Na fila','sending'=>'Enviando','retrying'=>'Nova tentativa','sent'=>'Enviada','failed'=>'Falhou','received'=>'Recebida',default=>$s!==''?ucfirst($s):'—'};
$modeLabel=static fn(string$m):string=>match($m){'waiting_human'=>'Aguardando atendente','human'=>'Atendimento humano','auto'=>'Automático',default=>'Atendimento'};
$modeTone=static fn(string$m):string=>match($m){'waiting_human'=>'warning','human'=>'success','auto'=>'info',default=>'muted'};
$filterLabels=['all'=>'Todas','waiting'=>'Aguardando','mine'=>'Minhas','unread'=>'Não lidas','human'=>'Humano','auto'=>'Automático'];
$latestMessageId=$messages?(int)end($messages)['id']:0;if($messages)reset($messages);

em_header('Central de Atendimento','communications');
?>
<style>
.support-shell{display:grid;grid-template-columns:minmax(260px,320px) minmax(380px,1fr) minmax(260px,340px);gap:14px;align-items:stretch;min-height:70vh}.support-pane{background:var(--surface,#fff);border:1px solid var(--line,#e8e5ef);border-radius:20px;overflow:hidden;min-width:0}.support-pane-head{padding:16px;border-bottom:1px solid var(--line,#e8e5ef)}.support-inbox{max-height:72vh;overflow:auto}.support-chat{display:flex;flex-direction:column;min-height:72vh}.support-messages{padding:18px;display:flex;flex-direction:column;gap:10px;overflow:auto;flex:1;max-height:58vh;background:linear-gradient(180deg,#faf9fc,#fff)}.support-bubble{max-width:82%;padding:10px 12px;border-radius:16px;border:1px solid #e7e3ee;background:#fff;box-shadow:0 1px 2px rgba(30,20,50,.04)}.support-bubble.inbound{align-self:flex-start;border-bottom-left-radius:5px}.support-bubble.outbound{align-self:flex-end;background:#f0ebff;border-color:#dfd4ff;border-bottom-right-radius:5px}.support-bubble p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.support-meta{display:flex;gap:7px;justify-content:flex-end;margin-top:6px;font-size:11px;color:#777}.support-conversation{display:block;padding:13px 14px;border-bottom:1px solid #eee;text-decoration:none;color:inherit}.support-conversation:hover,.support-conversation.active{background:#f7f4ff}.support-row{display:flex;justify-content:space-between;gap:8px;align-items:center}.support-preview{font-size:13px;color:#6f6a78;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:5px}.support-unread{min-width:24px;height:24px;padding:0 7px;border-radius:999px;background:#5b34d6;color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:12px}.support-compose{padding:14px;border-top:1px solid #eee}.support-compose textarea{width:100%;resize:vertical;min-height:76px}.support-side{max-height:72vh;overflow:auto;padding:16px}.support-card{padding:13px;border:1px solid #ece8f2;border-radius:14px;margin-bottom:12px}.support-order-items{margin:8px 0 0;padding-left:18px}.support-filter{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.support-filter a{padding:7px 10px;border-radius:999px;border:1px solid #ddd;text-decoration:none;color:inherit;font-size:12px}.support-filter a.active{background:#21134f;color:#fff;border-color:#21134f}.support-empty{padding:30px;text-align:center;color:#777}.support-search{display:flex;gap:6px}.support-search input{min-width:0;flex:1}.support-actions{display:flex;gap:7px;flex-wrap:wrap}.support-note{font-size:12px;color:#6f6a78}.support-media{display:inline-block;margin-top:8px}.support-order-row{padding:8px 0;border-bottom:1px solid #eee}.support-order-row:last-child{border:0}@media(max-width:1120px){.support-shell{grid-template-columns:290px 1fr}.support-context{grid-column:1/-1}.support-side{max-height:none}}@media(max-width:760px){.support-shell{grid-template-columns:1fr}.support-inbox{max-height:38vh}.support-chat{min-height:65vh}.support-messages{max-height:52vh}.support-context{grid-column:auto}}
</style>
<section class="page-hero"><div><span class="eyebrow">WHATSAPP · ATENDIMENTO</span><h2>Central de Atendimento</h2><p>Converse com clientes sem abrir o WhatsApp no navegador. As respostas entram na mesma fila persistente e são enviadas pelo EventMenu Connect.</p></div><div class="hero-actions"><button class="button primary" type="button" onclick="document.getElementById('newConversation').showModal()">+ Nova conversa</button><a class="button secondary" href="<?=Security::e(app_url('whatsapp.php'))?>">Configurar WhatsApp</a><button class="button secondary" type="button" onclick="location.reload()">Atualizar</button></div></section>
<dialog id="newConversation" style="border:0;border-radius:20px;max-width:520px;width:calc(100% - 28px);padding:0;box-shadow:0 24px 80px #0003"><form method="post" style="padding:22px"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="start"><div class="support-row"><div><span class="eyebrow">NOVO ATENDIMENTO</span><h3 style="margin:.3rem 0">Iniciar conversa</h3></div><button type="button" class="button secondary compact" onclick="document.getElementById('newConversation').close()">Fechar</button></div><label>WhatsApp com DDD</label><input name="phone" inputmode="tel" autocomplete="tel" required placeholder="Ex.: 22999999999" style="width:100%;margin:6px 0 14px"><label>Primeira mensagem <span class="muted">(opcional)</span></label><textarea name="message" maxlength="4000" placeholder="Olá! Como podemos ajudar?" style="width:100%;min-height:110px;margin:6px 0 14px"></textarea><p class="support-note">A conversa será assumida por você. O envio passa pela fila e pelo EventMenu Connect.</p><button class="primary" type="submit">Abrir conversa</button></form></dialog>
<div class="metric-grid" style="margin-bottom:14px"><div class="metric-card"><span>Aguardando</span><strong data-counter="waiting"><?=(int)$counters['waiting']?></strong></div><div class="metric-card"><span>Minhas</span><strong data-counter="mine"><?=(int)$counters['mine']?></strong></div><div class="metric-card"><span>Não lidas</span><strong data-counter="unread"><?=(int)$counters['unread']?></strong></div><div class="metric-card"><span>Total</span><strong data-counter="total"><?=(int)$counters['total']?></strong></div></div>
<div class="support-shell">
<aside class="support-pane"><div class="support-pane-head"><form class="support-search" method="get" action="<?=Security::e(app_url('support.php'))?>"><input type="hidden" name="filter" value="<?=Security::e($filter)?>"><input name="q" value="<?=Security::e($search)?>" placeholder="Nome, telefone ou e-mail"><button class="button secondary compact">Buscar</button></form><div class="support-filter"><?php foreach($filterLabels as$key=>$label):$url=$backUrl(['filter'=>$key]);?><a class="<?=$filter===$key?'active':''?>" href="<?=Security::e($url)?>"><?=Security::e($label)?><?php if($key==='waiting'):?> (<?=(int)$counters['waiting']?>)<?php elseif($key==='mine'):?> (<?=(int)$counters['mine']?>)<?php elseif($key==='unread'):?> (<?=(int)$counters['unread']?>)<?php endif;?></a><?php endforeach;?></div></div><div class="support-inbox"><?php if(!$inbox):?><div class="support-empty">Nenhuma conversa encontrada.</div><?php else:foreach($inbox as$row):$url=$backUrl(['id'=>(int)$row['id']]);$display=trim((string)($row['customer_name']??''))?:('WhatsApp '.substr((string)$row['phone'],-4));?><a class="support-conversation <?=$selectedId===(int)$row['id']?'active':''?>" href="<?=Security::e($url)?>"><div class="support-row"><strong><?=Security::e($display)?></strong><small><?=Security::e(em_elapsed_label((string)$row['last_activity_at']))?></small></div><div class="support-row"><span class="badge status-<?=$modeTone((string)$row['mode'])?>"><?=Security::e($modeLabel((string)$row['mode']))?></span><?php if((int)$row['unread_count']>0):?><span class="support-unread"><?=(int)$row['unread_count']?></span><?php endif;?></div><div class="support-preview"><?=Security::e(trim((string)($row['last_message']??''))?:'Mídia / mensagem sem texto')?></div><?php if(!empty($row['assigned_user_name'])):?><div class="support-note">Com <?=Security::e((string)$row['assigned_user_name'])?></div><?php endif;?></a><?php endforeach;endif;?></div></aside>
<main class="support-pane support-chat"><?php if(!$selected):?><div class="support-empty">Selecione uma conversa para abrir o atendimento.</div><?php else:?><div class="support-pane-head"><div class="support-row"><div><strong><?=Security::e(trim((string)($selected['customer_name']??''))?:'Cliente WhatsApp')?></strong><div class="support-note">+<?=Security::e((string)$selected['phone'])?> · <?=Security::e($modeLabel((string)$selected['mode']))?></div></div><div class="support-actions"><?php if((string)$selected['mode']==='waiting_human'):?><form method="post"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="assume"><input type="hidden" name="conversation_id" value="<?=(int)$selected['id']?>"><button class="primary" type="submit">Assumir atendimento</button></form><?php elseif((string)$selected['mode']==='human'&&(int)$selected['assigned_user_id']===(int)Auth::id()):?><form method="post" onsubmit="return confirm('Devolver esta conversa para o atendimento automático?')"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="resume"><input type="hidden" name="conversation_id" value="<?=(int)$selected['id']?>"><button class="secondary" type="submit">Voltar ao automático</button></form><?php endif;?></div></div><?php if((string)$selected['mode']==='human'&&!empty($selected['assigned_user_name'])):?><div class="support-note">Atendimento com <?=Security::e((string)$selected['assigned_user_name'])?><?=!empty($selected['assigned_at'])?' desde '.Security::e((string)$selected['assigned_at']):''?>.</div><?php endif;?></div><div class="support-messages" id="supportMessages"><?php if(!$messages):?><div class="support-empty">Ainda não há mensagens nesta conversa.</div><?php else:foreach($messages as$message):$direction=(string)$message['direction'];$text=trim((string)($message['message_text']??''));?><article class="support-bubble <?=$direction==='outbound'?'outbound':'inbound'?>"><?php if($text!==''):?><p><?=Security::e($text)?></p><?php else:?><p class="muted">[<?=Security::e((string)$message['message_type'])?>]</p><?php endif;?><?php if(!empty($message['media']['url'])):?><a class="support-media" href="<?=Security::e((string)$message['media']['url'])?>" target="_blank" rel="noopener noreferrer"><?=Security::e((string)($message['media']['filename']?:'Abrir mídia'))?></a><?php endif;?><div class="support-meta"><span><?=Security::e((string)($message['provider_created_at']?:$message['created_at']))?></span><?php if($direction==='outbound'):?><span><?=Security::e($statusLabel((string)$message['status']))?></span><?php endif;?></div></article><?php endforeach;endif;?></div><div class="support-compose"><?php if((string)$selected['mode']==='human'&&(int)$selected['assigned_user_id']===(int)Auth::id()):?><form method="post"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="send"><input type="hidden" name="conversation_id" value="<?=(int)$selected['id']?>"><textarea id="supportComposer" name="message" maxlength="4000" required placeholder="Digite uma resposta..."></textarea><div class="support-row"><span class="support-note">O navegador apenas cria o job. Quem envia é o EventMenu Connect/Baileys.</span><button class="primary" type="submit">Enviar</button></div></form><?php elseif((string)$selected['mode']==='waiting_human'):?><div class="alert">Assuma o atendimento para responder. Enquanto isso, o bot continua pausado.</div><?php elseif((string)$selected['mode']==='human'):?><div class="alert">Esta conversa está sendo atendida por <?=Security::e((string)($selected['assigned_user_name']?:'outro atendente'))?>.</div><?php else:?><div class="alert">Atendimento automático ativo. O campo manual fica bloqueado para evitar respostas simultâneas.</div><?php endif;?></div><?php endif;?></main>
<aside class="support-pane support-context"><div class="support-side"><?php if(!$selected):?><div class="support-empty">O contexto do cliente aparece aqui.</div><?php else:?><div class="support-card"><span class="eyebrow">CLIENTE</span><h3><?=Security::e(trim((string)($selected['customer_name']??''))?:'Não identificado')?></h3><p>+<?=Security::e((string)$selected['phone'])?></p><?php if(!empty($selected['customer_email'])):?><p class="muted"><?=Security::e((string)$selected['customer_email'])?></p><?php endif;?><?php if((int)($selected['customer_id']??0)>0):?><a class="button secondary compact" href="<?=Security::e(app_url('?route=customers&view='.(int)$selected['customer_id']))?>">Abrir cadastro</a><?php endif;?></div><?php if($activeOrder):?><div class="support-card"><span class="eyebrow">PEDIDO ATUAL</span><div class="support-row"><h3>#<?=(int)$activeOrder['id']?></h3><?=em_status_badge((string)$activeOrder['status'])?></div><p><?=Security::e(em_channel_label((string)$activeOrder['channel']))?> · <?=Security::e(em_status_label((string)$activeOrder['payment_status'],'payment'))?></p><strong><?=em_money((int)$activeOrder['total_cents'])?></strong><?php if(!empty($activeOrder['delivery_address'])):?><p class="support-note">Entrega: <?=Security::e((string)$activeOrder['delivery_address'])?></p><?php endif;?><?php if($activeItems):?><ul class="support-order-items"><?php foreach($activeItems as$item):?><li><?=Security::e((string)$item['quantity'])?>× <?=Security::e((string)$item['name_snapshot'])?></li><?php endforeach;?></ul><?php endif;?></div><?php endif;?><?php if($addresses):?><div class="support-card"><span class="eyebrow">ENDEREÇOS</span><h3>Endereços salvos</h3><?php foreach($addresses as$address):?><div class="support-order-row"><strong><?=Security::e((string)$address['label'])?><?=(int)$address['is_default']===1?' · Principal':''?></strong><div class="support-note"><?=Security::e((string)$address['address_text'])?></div></div><?php endforeach;?></div><?php endif;?><?php if($recentOrders):?><div class="support-card"><span class="eyebrow">HISTÓRICO</span><h3>Pedidos recentes</h3><?php foreach($recentOrders as$order):?><div class="support-order-row"><div class="support-row"><strong>#<?=(int)$order['id']?></strong><span><?=em_money((int)$order['total_cents'])?></span></div><div class="support-note"><?=Security::e(em_channel_label((string)$order['channel']))?> · <?=Security::e(em_status_label((string)$order['status']))?> · <?=Security::e((string)$order['created_at'])?></div></div><?php endforeach;?></div><?php endif;?><?php endif;?></div></aside>
</div>
<?php if($selected):$peek=json_encode($backUrl(['ajax'=>'peek','id'=>(int)$selected['id']]),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);?><script>(()=>{const messages=document.getElementById('supportMessages');if(messages)messages.scrollTop=messages.scrollHeight;const endpoint=<?=$peek?>;let latest=<?=$latestMessageId?>,lastMode=<?=json_encode((string)$selected['mode'])?>;setInterval(async()=>{try{const r=await fetch(endpoint,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}}),d=await r.json();if(!r.ok||!d.ok)return;for(const[k,v]of Object.entries(d.counters||{})){const el=document.querySelector(`[data-counter="${k}"]`);if(el)el.textContent=String(v)}const composer=document.getElementById('supportComposer'),busy=composer&&(document.activeElement===composer||composer.value.trim()!=='');if(!busy&&((d.latest_message_id||0)!==latest||(d.mode||'')!==lastMode))location.reload()}catch{}},5000)})();</script><?php endif;?>
<?php em_footer(); ?>
